b.request:
{
  "agent": "Claude" | "Codex",
  "remainPct": number,        // 0..100
  "resetAt"?: string,
  "tokensUsed"?: number       // 직전 보고 이후
}

{
  "items": [{
    "taskKey": string,
    "estHours": number, "loHours": number, "hiHours": number,
    "tokensK"?: number,
    "confidence": "상" | "중" | "하",
    "basis": string,
    "agreedBy": ("Claude" | "Codex")[]
  }]
}

{
  "agent": "Claude" | "Codex",
  "models": [{ "id": string, "label": string, "rank": number }],
  "efforts": string[]          // CLI 고유 값, 낮은 순
}

b.response:
200 {
  "model": string, "effort": string,
  "locked": boolean,
  "floorEffort": string,
  "allowedModels": string[],
  "policy": {
    "onUsage": "wait" | "down", "lowPct": number,
    "onRework": "same" | "up1" | "top", "notifyAt": number
  }
}

b.request:
{
  "at": string,
  "limit": number,              // Runner가 조절한 현재 한도 (팀장 상한 이하)
  "running": { "Claude": number, "Codex": number },   // 세션 + 하위 Agent
  "subagents": number,
  "heavyJobs": number,
  "resources": { "cpuPct": number, "memFreeGB": number, "swapGB": number },
  "adjust"?: { "from": number, "to": number, "reason": string }
}

b.response:
200 {
  "enabled": boolean,
  "items": [{ "id": string, "agent": "Claude" | "Codex", "version": number, "hash": string,
    "file": string,            // .claude/agents/<id>.md 또는 .codex/agents/<id>.toml 내용
    "sandbox": string }]
}
